{"contents":[{"uri":"horizun://contract/tools/horizun_family_apply","mimeType":"application/json","text":"{
  "name": "horizun_family_apply",
  "command": "horizun_family_apply",
  "description": "Homologate the ACTIVE family document (.rfa) in ONE transaction: collapse surplus types down to one and rename it to family_name, add missing shared parameters from an SPF (respecting instance/type and the parameter group), clear formulas on the parameters about to be written (a formula-driven parameter refuses a value), set values, remove named parameters (the caller's parameter spec's 'NA' entries), and strip vendor junk under the conservative rule: String storage, no formula, matches a junk pattern, not excluded, not kept, not in the caller-supplied protected prefix (protected_prefix). TWO checks run. A PARAMETER SCHEMA CHECK IS ENFORCED, NOT LOGGED (it is NOT a geometry check and is no longer called one): the count of Double parameters and the presence of IsCustom are captured before, re-enumerated fresh after the writes, and if either changed â€” or if either census could not be read completely â€” the WHOLE transaction is rolled back and the family is left untouched. Every reported field is a fresh read of the family document after the commit: params_set reports value_written vs value_read_back and a mismatch is a failure, type_name_after comes from fm.CurrentType.Name, params_added/params_removed are counted by re-reading fm.Parameters and never by counting calls that did not throw (FamilyManager.Set and RemoveParameter return void â€” there is not even a bool to check). Never opens a file: rfa_path is a guard that must match the active document, because opening a 2025 .rfa in Revit 2026 upgrades it irreversibly. SEPARATELY, the SHAPE is measured: bounding box, solid volume, surface area, solid count and connector positions of the ACTIVE family type are captured before and compared after, and reported in geometry_check as unchanged / unchanged_where_measured / unproven (zero dimensions compared - a verdict that measured nothing does not wear the word of a clean pass) / changed. Only the active type is measured, because activating another type to measure it would itself modify the file - the others are listed as not verified rather than assumed intact. Idempotent: a second run reports nothing to do, not an error. Use dry_run=true to see the plan without a transaction.",
  "effect": "MutatingUnlessDryRun",
  "destructive": false,
  "open_world": false,
  "toolsets": [
    "family"
  ],
  "external_content": true,
  "input_schema": {
    "type": "object",
    "properties": {
      "confirmation_token": {
        "type": "string",
        "description": "REQUIRED when dry_run=false. The token returned by the dry run of this exact request. Single-use, expires, and bound to this document and this request - if either changed, execution is refused and nothing is written."
      },
      "rfa_path": {
        "type": "string",
        "description": "GUARD, not an instruction to open anything. If given, the run aborts unless it resolves to the ACTIVE family document's PathName. This handler never calls OpenDocumentFile: opening a 2025 .rfa from Revit 2026 upgrades the file irreversibly and breaks the family catalog. Open the family yourself (or via horizun_document_session) in the right Revit, then pass its path here to prove this is the one."
      },
      "expected_revit_version": {
        "type": "string",
        "description": "GUARD, e.g. '2025'. Aborts unless the running Revit reports this VersionNumber. The families are 2025; saving one from 2026 upgrades it with no way back."
      },
      "family_name": {
        "type": "string",
        "description": "The canonical Family Name (no .rfa). Given, the family is collapsed to exactly ONE type named this. Omitted, no type is created, deleted or renamed."
      },
      "keep_type": {
        "type": "string",
        "description": "Which existing type survives the collapse. Default: the one already named family_name, else the first. Every other type is deleted, so name it when the family carries real different sizes â€” those must be split into one family per size BEFORE this runs, not collapsed here."
      },
      "collapse_types": {
        "type": "boolean",
        "default": true,
        "description": "With family_name set: delete the surplus types. false renames the surviving/current type only and leaves the others alone."
      },
      "spf_path": {
        "type": "string",
        "description": "Your shared parameter file (the .txt Revit exports for a Shared Parameter File) to take add_shared_params from. The app's SharedParametersFilename is restored afterwards."
      },
      "add_shared_params": {
        "type": "array",
        "description": "Shared parameters to add if missing. A parameter already present is left exactly as it is (idempotence), never re-added.",
        "items": {
          "type": "object",
          "required": [
            "name"
          ],
          "properties": {
            "name": {
              "type": "string",
              "description": "Definition name as it reads in the SPF."
            },
            "instance": {
              "type": "boolean",
              "default": false,
              "description": "true = instance parameter, carrying its own value per placed element. false (default) = type parameter, one value shared by every instance of the type. Pick instance only for values that must vary per occurrence."
            },
            "group": {
              "type": "string",
              "default": "PG_DATA",
              "description": "Parameter group: 'PG_DATA', 'PG_IDENTITY_DATA', a GroupTypeId name ('Data', 'IdentityData'), or a full group ForgeTypeId. A group that cannot be resolved is an ERROR for that row â€” never a silent fallback to Data, which would file the parameter in the wrong place and report success."
            }
          }
        }
      },
      "values": {
        "type": "object",
        "description": "{ parameter_name: value }. Set on the surviving type. String | number | boolean | null. A number on Double/Integer storage is raw Revit internal units; a STRING on Double/Integer goes through SetValueString (unit-aware) and can only be confirmed against a re-read of itself â€” those rows are reported separately and never claimed as verified against your value."
      },
      "clear_formulas": {
        "type": "boolean",
        "default": true,
        "description": "SetFormula(p, null) on a parameter in 'values' that is driven by a formula, BEFORE writing it. Imported families arrive with Description/Manufacturer/Material governed by a vendor formula, and Revit refuses a value on those ('Cannot set the value of a parameter determined by a formula'). false = such a row is refused and reported, never silently skipped."
      },
      "clear_formulas_on": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Extra parameter names to clear the formula of even though no value is written to them."
      },
      "remove_params": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "Parameters to delete by name â€” typically the caller's parameter spec's 'NA' entries. A name that is not in the family is 'nothing to do', not an error (idempotence). Revit refuses to remove a referenced parameter: that is reported as skipped with Revit's reason, never counted as removed."
      },
      "junk_rules": {
        "type": "object",
        "description": "Vendor metadata stripping (BIMobject/manufacturer families arrive with dozens â€” a Caleffi valve had 70). Off unless enabled.",
        "properties": {
          "enabled": {
            "type": "boolean",
            "default": false
          },
          "patterns": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "REQUIRED when enabled. Lowercase substrings that mark a parameter as junk. There is NO default list: what counts as vendor junk depends on whose families these are, and a built-in list would delete parameters by rules you never read. This command owns HOW to strip safely - match, veto, protect, one transaction, verify by re-reading, roll back if the parameter census moved; WHAT to strip is yours to state."
          },
          "exclude": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional. Lowercase substrings that VETO removal even on a junk match. Empty means veto nothing. IsCustom is refused regardless of this list, because it moves geometry - that is a fact about Revit, not a policy."
          },
          "keep": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional. Exact names (lowercased) never removed. Empty means keep nothing by name."
          }
        }
      },
      "protected_prefix": {
        "type": "string",
        "description": "Optional caller-supplied prefix. Parameters whose name starts with it are counted in the census (protected_prefix_count_before/after) and are never removed by the junk sweep â€” remove_params can still delete one by exact name. Omitted: they are not tracked at all, and the counts are reported as null, which is NOT the same as zero."
      },
      "save": {
        "type": "boolean",
        "default": false,
        "description": "doc.Save() in place after a successful commit. Never SaveAs, never a rename, never a delete of the original â€” an earlier scripted approach lost a family that way. saved_path is reported only after the file is found on disk, re-read from disk as a real family file, AND PROVEN TO HAVE CHANGED: size, timestamp and a SHA-256 of the contents are taken BEFORE the save and compared after, because a valid file that was already there is not evidence that Save wrote anything. A save that leaves the bytes identical is reported as saved=false with both hashes, since the commit already changed the family in memory and the file on disk is now behind it. The response also states whether a recoverable backup was left beside it. A rolled-back run never saves."
      },
      "target_document": {
        "type": "string",
        "description": "REQUIRED. Title or full path of the document to write to. It must be the document that is ACTIVE in Revit; this command will not switch documents for you. A write aimed at whatever window happens to be in front is a write aimed at whatever turns up."
      },
      "dry_run": {
        "type": "boolean",
        "default": true,
        "description": "Resolve everything and report the plan and the before-census. Opens no transaction and saves nothing."
      },
      "transaction_name": {
        "type": "string",
        "default": "Horizun: homologar familia",
        "description": "The label of the single undo step this becomes."
      },
      "idempotency_key": {
        "type": "string",
        "minLength": 1,
        "maxLength": 200,
        "description": "REQUIRED whenever this call will mutate or change the Revit session. A retry with the same key and identical operation returns the recorded result without executing twice. Reusing it for different arguments is refused. Generate a new UUID for each deliberate operation; keep it unchanged only for retries."
      }
    }
  },
  "output_schema": {
    "type": "object",
    "additionalProperties": true
  }
}"}]}

