            "description": "{column: parameter} - each mapped column writes that parameter.",
            "additionalProperties": {
              "type": "string"
            }
          },
          "category": {
            "type": "string",
            "description": "OST_ BuiltInCategory bounding the element sweep. Required: an unbounded sweep is not a cost to impose silently."
          },
